const ThirdParty = () => {
  return (
    <div className="mt-4">
        <h2 className='text-gray-800 font-extrabold text-[16px] md:text-[18px] underline'>Third party information</h2>
        <p className='text-md lg:text-lg mt-4'>Third party information can be any data that you provide to us that is not related to you. This can include for example, the delivery details that you provide if you are shipping the order to some one else, or photos of others in your uploaded photos. Please ensure that you have prior permission from others before uploading their photos. We treat third party information no different from yours, and is subject to same strict controls and privacy policy.</p>
    </div>
  )
}

export default ThirdParty
